-- Phase 39: import submitted game denominations and telecom/PLN catalog.
-- Imported prices are deliberately 0 until the operator/provider price is verified in admin.
-- Top-up checkout must remain blocked for zero-price packages.
ALTER TABLE packages ADD COLUMN IF NOT EXISTS provider_code text NOT NULL DEFAULT '';

ON CONFLICT (slug) DO NOTHING;

ON CONFLICT (slug) DO NOTHING;

-- Attach source codes to existing seeded PLN rows without changing their current selling prices.
UPDATE packages p SET provider_code = v.code, description = 'Kode produk: ' || v.code || ' — harga perlu diverifikasi admin'
FROM brands b, (VALUES ('Token 20.000','TKNPLN20'),('Token 50.000','TKNPLN50'),('Token 100.000','TKNPLN100')) AS v(name, code)
WHERE p.brand_id=b.id AND b.slug='pln-prabayar' AND lower(p.name)=lower(v.name) AND coalesce(p.provider_code,'')='';

